import os, py_compile, pathlib, filecmp
t = pathlib.Path(os.environ['TARGET_DIR'])
o = pathlib.Path(os.environ['ORIGINAL_DIR'])
changed = []
for root, dirs, files in os.walk(t):
    for f in files:
        if f.endswith('.py'):
            p = pathlib.Path(root) / f
            rel = p.relative_to(t)
            q = o / rel
            if not q.exists() or not filecmp.cmp(p, q, shallow=False):
                try:
                    py_compile.compile(str(p), doraise=True)
                    changed.append(str(p))
                except Exception as e:
                    print('Syntax error in', p, e)
                    raise
print('Syntax check completed. Modified Python files:', changed)
